static uint32_t NVIC_ISER_BAK[5];
static uint8_t  m_u8HrcState = 0U;
static uint8_t  m_u8MrcState = 0U;
static uint8_t  m_u8WkupIntCount = 0U;
static uint8_t  m_u8StopFlag = 0U;
static uint8_t  m_u8SysClockSource = 1U;
